import { collectingReporter, freePort, runSyncbox, sha256, startServer, type TestServer, writeTree } from "./helpers.js";

/** Every entry under `root` (files, directories, links), as sorted relative paths. */
async function tree(root: string): Promise<string[]> {
  return (await readdir(root, { recursive: true })).sort();
}

/** Seeds the server with `files` by pushing them from a scratch directory. */
async function seed(server: TestServer, scratch: string, files: Record<string, string | Buffer>): Promise<void> {
  await writeTree(scratch, files);
  const client = new SyncboxClient(server.url);
  try {
    await push(scratch, client, collectingReporter());
  } finally {
    client.close();
  }
}

/** A server that answers GET /blobs with `list` and everything else with `handler`. */
async function startFakeServer(
  list: unknown[],
  handler: (req: http.IncomingMessage, res: http.ServerResponse) => void,
): Promise<{ url: URL; requests: string[]; close(): Promise<void> }> {
  const requests: string[] = [];
  const server = http.createServer((req, res) => {
    requests.push(`${req.method} ${req.url}`);
    if (req.url === "/blobs") {
      res.writeHead(200, { "Content-Type": "application/json" }).end(JSON.stringify(list));
    } else {
      handler(req, res);
    }
  });
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  return {
    url: new URL(`http://127.0.0.1:${(server.address() as net.AddressInfo).port}/`),
    requests,
    async close() {
      server.closeAllConnections();
      server.close();
      await once(server, "close");
    },
  };
}

