function isCommand(value: string): value is Command {
  return (COMMANDS as readonly string[]).includes(value);
}

/**
 * Accepts an http(s) URL, optionally with a path prefix the API is mounted
 * under (`http://host/syncbox` → `http://host/syncbox/blobs`).
 */
export function parseServerUrl(raw: string): URL {
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    throw new UsageError(`invalid server URL: ${JSON.stringify(raw)} (expected e.g. http://127.0.0.1:8080)`);
  }
  if (url.protocol !== "http:" && url.protocol !== "https:") {
    throw new UsageError(`invalid server URL: ${JSON.stringify(raw)} (only http:// and https:// are supported)`);
  }
  if (url.search !== "" || url.hash !== "") {
    throw new UsageError(`invalid server URL: ${JSON.stringify(raw)} (must not contain a query or fragment)`);
  }
  if (!url.pathname.endsWith("/")) {
    url.pathname += "/";
  }
  return url;
}
import { createHash } from "node:crypto";
import http from "node:http";
import https from "node:https";
import { Transform, type Readable } from "node:stream";
import { pipeline } from "node:stream/promises";

/** A failure to report to the user as is (no stack trace). */
export class ClientError extends Error {
  override name = "ClientError";
}

export interface RemoteBlob {
  key: string;
  size: number;
  sha256: string;
  modified_at: string;
}

/** How long to wait for a TCP connection before giving up on the server. */
const CONNECT_TIMEOUT_MS = 10_000;

interface HttpResponse {
  status: number;
  statusText: string;
  body: Buffer;
}

/** URL of `/blobs/{key}`: each path segment percent-encoded, `/` kept. */
export function blobUrl(server: URL, key: string): URL {
  return new URL(`blobs/${key.split("/").map(encodeURIComponent).join("/")}`, server);
}

/**
 * Thin wrapper over the server's HTTP API (see syncbox-openapi.yaml). Built
 * on node:http rather than fetch(), which refuses to connect to a list of
 * "bad" ports (6000, 10080, ...) a server may well be listening on.
 */
export class SyncboxClient {
  private readonly agent: http.Agent;

  constructor(private readonly server: URL) {
    const Agent = server.protocol === "https:" ? https.Agent : http.Agent;
    this.agent = new Agent({ keepAlive: true });
  }

  /** Releases the kept-alive connections. */
  close(): void {
    this.agent.destroy();
  }

  async list(): Promise<RemoteBlob[]> {
    const what = "GET /blobs";
    const res = await this.request(what, "GET", new URL("blobs", this.server));
    if (res.status !== 200) {
      throw unexpectedStatus(what, res);
    }
    const body = parseJson(what, res);
    if (!Array.isArray(body) || !body.every(isRemoteBlob)) {
      throw new ClientError(`${what}: server returned an unexpected response`);
    }
    return body;
  }

  /**
   * Uploads `body` under `key` and checks that the server stored exactly the
   * bytes that were sent. Returns their SHA-256.
   */
  async put(key: string, body: Readable): Promise<string> {
    const what = `PUT ${key}`;
    const hash = createHash("sha256");
    const hashing = new Transform({
      transform(chunk: Buffer, _encoding, callback) {
        hash.update(chunk);
        callback(null, chunk);
      },
    });
    const res = await this.request(what, "PUT", blobUrl(this.server, key), body, hashing);
    if (res.status !== 201) {
      throw unexpectedStatus(what, res);
    }
    const stored = parseJson(what, res) as { sha256?: unknown } | null;
    const sent = hash.digest("hex");
    if (typeof stored !== "object" || stored === null || stored.sha256 !== sent) {
      throw new ClientError(`${what}: server reports a different SHA-256 than the uploaded content has`);
    }
    return sent;
  }

  /**
   * Downloads the blob stored under `key`. Resolves once the server has
   * answered 200, with the body still to be received: it has to be consumed
   * right away, chunk by chunk. Failures while receiving it are thrown from
   * the iteration as ClientError.
   */
  async get(key: string): Promise<AsyncIterable<Buffer>> {
    const what = `GET ${key}`;
    const res = await this.send(what, "GET", blobUrl(this.server, key));
    if (res.statusCode !== 200) {
      throw unexpectedStatus(what, await this.receive(what, res));
    }
    return this.chunks(what, res);
  }

  /** Sends a request and reads the whole response. */
  private async request(what: string, method: string, url: URL, body?: Readable, via?: Transform): Promise<HttpResponse> {
    return this.receive(what, await this.send(what, method, url, body, via));
  }

  private async receive(what: string, res: http.IncomingMessage): Promise<HttpResponse> {
    const chunks: Buffer[] = [];
    for await (const chunk of this.chunks(what, res)) {
      chunks.push(chunk);
    }
    return { status: res.statusCode ?? 0, statusText: res.statusMessage ?? "", body: Buffer.concat(chunks) };
  }

  private async *chunks(what: string, res: http.IncomingMessage): AsyncGenerator<Buffer> {
    try {
      for await (const chunk of res) {
        yield chunk as Buffer;
      }
    } catch (err) {
      throw this.failed(what, err);
    }
    if (!res.complete) {
      throw this.failed(what, new Error("connection closed before the response was complete"));
    }
  }

  /**
   * Sends a request, streaming `body` through `via` (if given) into it, and
   * resolves with the response as soon as its headers are in.
   */
  private send(what: string, method: string, url: URL, body?: Readable, via?: Transform): Promise<http.IncomingMessage> {
    return new Promise<http.IncomingMessage>((resolve, reject) => {
      const fail = (err: unknown): void => {
        req.destroy();
        reject(this.failed(what, err));
      };

      const transport = url.protocol === "https:" ? https : http;
      const req = transport.request(
        url,
        {
          method,
          agent: this.agent,
          headers: body === undefined ? {} : { "Content-Type": "application/octet-stream" },
        },
        (res) => {
          // Errors reach whoever reads the body (through the stream's state);
          // this only keeps one that comes before reading starts, or after it
          // was abandoned, from being an uncaught 'error' event.
          res.on("error", () => {});
          resolve(res);
        },
      );
      req.on("error", fail);

      // Only the connection setup is time-limited: a server that is merely
      // slow (hashing a large store for GET /blobs, say) is not an error.
      req.on("socket", (socket) => {
        if (!socket.connecting) return;
        const timer = setTimeout(() => fail(new Error(`no connection within ${CONNECT_TIMEOUT_MS / 1000}s`)), CONNECT_TIMEOUT_MS);
        socket.once("connect", () => clearTimeout(timer));
        socket.once("close", () => clearTimeout(timer));
      });

      if (body === undefined) {
        req.end();
      } else {
        const upload = via === undefined ? pipeline(body, req) : pipeline(body, via, req);
        upload.catch(fail);
      }
    });
  }

  private failed(what: string, err: unknown): ClientError {
    return err instanceof ClientError ? err : new ClientError(`${what}: request to ${this.server.origin} failed: ${describeError(err)}`);
  }
}

function isRemoteBlob(value: unknown): value is RemoteBlob {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return typeof v.key === "string" && typeof v.size === "number" && typeof v.sha256 === "string";
}

function parseJson(what: string, res: HttpResponse): unknown {
  try {
    return JSON.parse(res.body.toString("utf8"));
  } catch {
    throw new ClientError(`${what}: server returned a response that is not valid JSON`);
  }
}

function unexpectedStatus(what: string, res: HttpResponse): ClientError {
  let detail = "";
  try {
    const parsed = JSON.parse(res.body.toString("utf8")) as { error?: unknown };
    if (typeof parsed.error === "string") detail = `: ${parsed.error}`;
  } catch {
    // Not the server's JSON error format: the status alone has to do.
  }
  return new ClientError(`${what}: server responded ${res.status} ${res.statusText}${detail}`.trimEnd());
}

/**
 * A readable reason for a failed request. With several addresses to try
 * (localhost → ::1 and 127.0.0.1), connect errors come as an AggregateError
 * without a message of its own.
 */
function describeError(err: unknown): string {
  if (err instanceof AggregateError && err.errors.length > 0) {
    return describeError(err.errors[0]);
  }
  if (err instanceof Error) {
    return err.message || ((err as NodeJS.ErrnoException).code ?? err.name);
  }
  return String(err);
}
import { CLIENT_USAGE, parseClientArgs, UsageError } from "./cli.js";
import { ClientError, SyncboxClient } from "./client.js";
import { pull } from "./pull.js";
import { push, type Reporter } from "./push.js";

const EXIT_FAILURE = 1;
const EXIT_USAGE = 2;

const reporter: Reporter = {
  info: (line) => console.log(line),
  warn: (line) => console.error(`syncbox: warning: ${line}`),
};

async function main(): Promise<number> {
  let parsed;
  try {
    parsed = parseClientArgs(process.argv.slice(2), process.env);
  } catch (err) {
    if (err instanceof UsageError) {
      console.error(`syncbox: ${err.message}\n\n${CLIENT_USAGE}`);
      return EXIT_USAGE;
    }
    throw err;
  }

  if (parsed.kind === "help") {
    console.log(CLIENT_USAGE);
    return 0;
  }

  const { command, dir, server } = parsed.config;
  if (command !== "push" && command !== "pull") {
    console.error(`syncbox: '${command}' is not implemented yet (only 'push' and 'pull' are available)`);
    return EXIT_FAILURE;
  }

  const client = new SyncboxClient(server);
  try {
    if (command === "push") {
      const summary = await push(dir, client, reporter);
      console.log(`push: ${summary.uploaded.length} uploaded, ${summary.unchanged.length} unchanged${skipped(summary.skipped)}`);
    } else {
      const summary = await pull(dir, client, reporter);
      console.log(`pull: ${summary.downloaded.length} downloaded, ${summary.unchanged.length} unchanged${skipped(summary.skipped)}`);
    }
    return 0;
  } catch (err) {
    if (err instanceof ClientError) {
      console.error(`syncbox: ${command} failed: ${err.message}`);
      return EXIT_FAILURE;
    }
    throw err;
  } finally {
    client.close();
  }
}

function skipped(count: number): string {
  return count > 0 ? `, ${count} skipped` : "";
}

main().then(
  (code) => {
    process.exitCode = code;
  },
  (err: unknown) => {
    console.error("syncbox: fatal error:", err);
    process.exit(EXIT_FAILURE);
  },
);
import { createHash } from "node:crypto";
import { createReadStream } from "node:fs";
import { readdir, stat } from "node:fs/promises";
import { join } from "node:path";

import { decodeUtf8 } from "./blobs.js";
import { ClientError, type SyncboxClient } from "./client.js";

export interface LocalFile {
  /** Relative POSIX path inside the scanned directory: the blob key. */
  key: string;
  path: string;
  size: number;
}

export interface Reporter {
  info(line: string): void;
  warn(line: string): void;
}

export interface PushSummary {
  uploaded: string[];
  unchanged: string[];
  /** Directory entries that can't be pushed (links, special files, bad names). */
  skipped: number;
}

/**
 * Uploads every file under `dir` that the server doesn't have or has with a
 * different SHA-256; files the server already has with the same content are
 * left alone. Nothing on the server is deleted. Stops at the first failure.
 */
export async function push(dir: string, client: SyncboxClient, reporter: Reporter): Promise<PushSummary> {
  await assertDirectory(dir);
  // Ask the server first: if it is unreachable, there's no point in hashing.
  const remote = new Map((await client.list()).map((blob) => [blob.key, blob]));
  const { files, skipped } = await scanDir(dir, reporter);

  const summary: PushSummary = { uploaded: [], unchanged: [], skipped };
  for (const file of files) {
    const existing = remote.get(file.key);
    // A different size already means different content: no need to hash.
    if (existing !== undefined && existing.size === file.size && (await hashFile(file)) === existing.sha256) {
      summary.unchanged.push(file.key);
      continue;
    }
    await client.put(file.key, createReadStream(file.path));
    summary.uploaded.push(file.key);
    reporter.info(`uploaded ${file.key}`);
  }
  return summary;
}

export async function assertDirectory(dir: string): Promise<void> {
  let st;
  try {
    st = await stat(dir);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") throw new ClientError(`${dir}: no such directory`);
    throw new ClientError(`${dir}: ${(err as Error).message}`);
  }
  if (!st.isDirectory()) throw new ClientError(`${dir}: not a directory`);
}

/**
 * Lists the regular files under `root` recursively, sorted by key. Symbolic
 * links and special files are skipped with a warning, and so are names that
 * aren't valid UTF-8, since no key can represent them. Empty directories
 * have no blob counterpart and simply produce nothing.
 */
export async function scanDir(root: string, reporter: Reporter): Promise<{ files: LocalFile[]; skipped: number }> {
  const files: LocalFile[] = [];
  let skipped = 0;

  const walk = async (dir: string, prefix: string): Promise<void> => {
    let entries;
    try {
      entries = await readdir(dir, { withFileTypes: true, encoding: "buffer" });
    } catch (err) {
      throw new ClientError(`cannot read directory ${prefix === "" ? "." : prefix}: ${(err as Error).message}`);
    }
    for (const entry of entries) {
      const name = decodeUtf8(entry.name);
      if (name === undefined) {
        reporter.warn(`skipping ${prefix}${entry.name.toString("utf8")}: name is not valid UTF-8`);
        skipped++;
        continue;
      }
      const key = prefix + name;
      const path = join(dir, name);
      if (entry.isDirectory()) {
        await walk(path, `${key}/`);
      } else if (entry.isFile()) {
        let st;
        try {
          st = await stat(path);
        } catch (err) {
          throw new ClientError(`cannot read ${key}: ${(err as Error).message}`);
        }
        files.push({ key, path, size: st.size });
      } else {
        reporter.warn(`skipping ${key}: ${entry.isSymbolicLink() ? "symbolic link" : "not a regular file"}`);
        skipped++;
      }
    }
  };

  await walk(root, "");
  files.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
  return { files, skipped };
}

export async function hashFile(file: LocalFile): Promise<string> {
  const hash = createHash("sha256");
  try {
    for await (const chunk of createReadStream(file.path)) {
      hash.update(chunk as Buffer);
    }
  } catch (err) {
    throw new ClientError(`cannot read ${file.key}: ${(err as Error).message}`);
  }
  return hash.digest("hex");
}
import { createHash, randomUUID } from "node:crypto";
import { lstat, mkdir, open, rename, rm } from "node:fs/promises";
import { dirname, join } from "node:path";

import { ClientError, type RemoteBlob, type SyncboxClient } from "./client.js";
import { assertDirectory, hashFile, type LocalFile, type Reporter } from "./push.js";

export interface PullSummary {
  downloaded: string[];
  unchanged: string[];
  /** Blobs that can't be pulled (unusable keys, links or special files in the way). */
  skipped: number;
}

/** What is at a key's path in the local directory. */
type LocalEntry = { kind: "missing" } | ({ kind: "file" } & LocalFile) | { kind: "skip"; reason: string };

/**
 * Downloads every blob the server has that is missing under `dir` or differs
 * from the local file by SHA-256, creating subdirectories as needed; files
 * that already have the server's content are left alone. Nothing local is
 * deleted. Each file is written to a temporary file next to it and renamed
 * into place, so it is never left half-written. Stops at the first failure.
 */
export async function pull(dir: string, client: SyncboxClient, reporter: Reporter): Promise<PullSummary> {
  await assertDirectory(dir);
  const remote = (await client.list()).sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));

  const summary: PullSummary = { downloaded: [], unchanged: [], skipped: 0 };
  for (const blob of remote) {
    const segments = keySegments(blob.key);
    if (segments === undefined) {
      reporter.warn(`skipping ${JSON.stringify(blob.key)}: not a relative path inside the directory`);
      summary.skipped++;
      continue;
    }
    const local = await inspect(dir, blob.key, segments);
    if (local.kind === "skip") {
      reporter.warn(`skipping ${blob.key}: ${local.reason}`);
      summary.skipped++;
      continue;
    }
    // A different size already means different content: no need to hash.
    if (local.kind === "file" && local.size === blob.size && (await hashFile(local)) === blob.sha256) {
      summary.unchanged.push(blob.key);
      continue;
    }
    await download(client, blob, join(dir, ...segments));
    summary.downloaded.push(blob.key);
    reporter.info(`downloaded ${blob.key}`);
  }
  return summary;
}

/**
 * Splits a key from the server's list into path segments, or returns
 * undefined if it isn't a relative POSIX path that stays inside the
 * directory. The server refuses to store such keys; this doesn't rely on it.
 */
function keySegments(key: string): string[] | undefined {
  if (key === "" || key.startsWith("/") || key.includes("\0")) return undefined;
  // Lone surrogates would end up as U+FFFD in the file name: another key.
  if (Buffer.from(key, "utf8").toString("utf8") !== key) return undefined;
  const segments = key.split("/");
  if (segments.some((s) => s === "" || s === "." || s === "..")) return undefined;
  return segments;
}

/**
 * Looks at what is at the key's path, without following symbolic links: a
 * link (to a file or along the way) is skipped rather than written through
 * or replaced, just as push skips links. So are special files. A directory
 * where the file belongs, or a file where a directory belongs, is an error.
 */
async function inspect(dir: string, key: string, segments: string[]): Promise<LocalEntry> {
  let path = dir;
  for (const [i, segment] of segments.entries()) {
    path = join(path, segment);
    const sub = segments.slice(0, i + 1).join("/");
    const last = i === segments.length - 1;
    let st;
    try {
      st = await lstat(path);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === "ENOENT") return { kind: "missing" };
      throw new ClientError(`cannot read ${sub}: ${(err as Error).message}`);
    }
    if (st.isSymbolicLink()) {
      return { kind: "skip", reason: last ? "symbolic link" : `${sub} is a symbolic link` };
    }
    if (!last) {
      if (!st.isDirectory()) throw new ClientError(`cannot write ${key}: ${sub} is not a directory`);
    } else if (st.isDirectory()) {
      throw new ClientError(`cannot write ${key}: it is a directory`);
    } else if (!st.isFile()) {
      return { kind: "skip", reason: "not a regular file" };
    } else {
      return { kind: "file", key, path, size: st.size };
    }
  }
  return { kind: "missing" };
}

/**
 * Streams the blob into a temporary file in the target's directory and,
 * once it is complete, flushed and has the SHA-256 the server listed,
 * renames it over the target. The temporary file is removed on failure.
 */
async function download(client: SyncboxClient, blob: RemoteBlob, target: string): Promise<void> {
  const writing = <T>(op: Promise<T>): Promise<T> =>
    op.catch((err: unknown) => {
      throw new ClientError(`cannot write ${blob.key}: ${(err as Error).message}`);
    });

  const tmp = join(dirname(target), `.syncbox-${randomUUID()}.tmp`);
  await writing(mkdir(dirname(target), { recursive: true }));
  const handle = await writing(open(tmp, "wx"));
  try {
    const hash = createHash("sha256");
    try {
      for await (const chunk of await client.get(blob.key)) {
        hash.update(chunk);
        for (let offset = 0; offset < chunk.length; ) {
          offset += (await writing(handle.write(chunk, offset))).bytesWritten;
        }
      }
      // Otherwise a crash shortly after the rename could leave the file
      // without its data.
      await writing(handle.datasync());
    } finally {
      await writing(handle.close());
    }
    if (hash.digest("hex") !== blob.sha256) {
      throw new ClientError(`GET ${blob.key}: received content does not match the SHA-256 the server listed (changed on the server meanwhile?)`);
    }
    await writing(rename(tmp, target));
  } catch (err) {
    await rm(tmp, { force: true });
    throw err;
  }
}
#!/bin/sh
# The Syncbox CLI client: `syncbox <push|pull|status|sync> <dir> --server <url>`.
# Runs the compiled entry point that sits next to this script's real location.
set -e
here="$(dirname "$(readlink -f "$0")")"
exec node "$here/../dist/src/syncbox.js" "$@"
#!/usr/bin/env bash
# Runs the Syncbox CLI client (`syncbox`) in a Docker container (via docker
# compose) and exits with its exit code.
#
#   run-client <push|pull|status|sync> <dir> --server <url>
#
# Arguments are forwarded to the client as given, except <dir>: that host
# directory is bind-mounted into the container at /work and the client gets
# that path instead. --server falls back to SYNCBOX_SERVER. The container
# shares the host's network, so http://127.0.0.1:<port> reaches a server
# started with run-server.
set -euo pipefail

repo="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
mount_point=/work

# Only <dir> (the second positional argument) is picked out here; validating
# everything else is left to the client, so its usage errors stay the same.
args=()
dir=""
positional=0
while [[ $# -gt 0 ]]; do
  case "$1" in
    --server)
      args+=("$1")
      shift
      if [[ $# -gt 0 ]]; then args+=("$1"); shift; fi
      ;;
    -?*) args+=("$1"); shift ;;
    *)
      positional=$((positional + 1))
      if (( positional == 2 )) && [[ -n "$1" ]]; then
        dir="$1"
        args+=("$mount_point")
      else
        args+=("$1")
      fi
      shift
      ;;
  esac
done

cleanup=""
if [[ -n "$dir" ]]; then
  if [[ ! -e "$dir" ]]; then
    echo "run-client: $dir: no such directory" >&2
    exit 1
  fi
  if [[ ! -d "$dir" ]]; then
    echo "run-client: $dir: not a directory" >&2
    exit 1
  fi
  host_dir="$(cd -- "$dir" && pwd -P)"
else
  # No directory to work on (--help, usage errors): mount an empty one.
  host_dir="$(mktemp -d)"
  cleanup="$host_dir"
fi
trap '[[ -z "$cleanup" ]] || rmdir -- "$cleanup"' EXIT

export SYNCBOX_CLIENT_DIR="$host_dir"
export SYNCBOX_UID="$(id -u)"
export SYNCBOX_GID="$(id -g)"

project="$(basename "$repo" | tr '[:upper:]' '[:lower:]' | tr -c 'a-z0-9_\n-' '-')"
project="${project%$'\n'}-client"

# --build is a no-op on a warm cache and picks up source changes otherwise;
# --progress quiet keeps the build output from mixing with the client's.
status=0
docker compose --progress quiet --project-directory "$repo" -f "$repo/compose.yaml" -p "$project" \
  run --rm --build -T client ${args[@]+"${args[@]}"} || status=$?
exit "$status"
#!/usr/bin/env bash
# Builds the test image and runs the whole test suite inside Docker (via
# docker compose). Exits non-zero if any test fails.
set -euo pipefail

repo="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

exec docker compose --project-directory "$repo" -f "$repo/compose.yaml" \
  run --rm --build -T test
# All Docker plumbing for Syncbox lives here. The run-server / run-client /
# run-tests wrappers only export the variables below and call
# `docker compose`.
#
#   SYNCBOX_HOST_DATA_DIR  host directory bind-mounted as the server's data dir
#                          (absolute path; default ./data in the repo)
#   SYNCBOX_PORT           port the server listens on, both in the container
#                          and on the host (default 8080)
#   SYNCBOX_PUBLISH_ADDR   host interface the port is published on
#                          (default 127.0.0.1; set 0.0.0.0 to expose on the LAN)
#   SYNCBOX_UID/GID        user the server and the client run as, so files in
#                          the data dir / synced dir belong to the invoking
#                          host user (default 1000)
#   SYNCBOX_CLIENT_DIR     host directory the client works on, bind-mounted at
#                          /work (absolute path; must be set for the client)
#   SYNCBOX_SERVER         passed through to the client (server URL fallback)

services:
  server:
    # Fixed tag: run-server uses a separate compose project per port, and
    # they should all share one image rather than each building its own.
    image: syncbox-server:local
    build:
      context: .
      target: server
    init: true
    # Docker's default bridge: no per-project network has to be created, so
    # several servers (on different ports) can be started concurrently.
    network_mode: bridge
    user: "${SYNCBOX_UID:-1000}:${SYNCBOX_GID:-1000}"
    environment:
      SYNCBOX_DATA_DIR: /data
      SYNCBOX_PORT: "${SYNCBOX_PORT:-8080}"
    ports:
      - "${SYNCBOX_PUBLISH_ADDR:-127.0.0.1}:${SYNCBOX_PORT:-8080}:${SYNCBOX_PORT:-8080}"
    volumes:
      - type: bind
        source: "${SYNCBOX_HOST_DATA_DIR:-./data}"
        target: /data
        bind:
          create_host_path: true

  client:
    image: syncbox-client:local
    build:
      context: .
      target: client
    profiles: [client]
    init: true
    # The server URL normally points at the host's loopback, where run-server
    # publishes its port; only the host's network namespace can reach that.
    network_mode: host
    user: "${SYNCBOX_UID:-1000}:${SYNCBOX_GID:-1000}"
    environment:
      - SYNCBOX_SERVER
    volumes:
      - type: bind
        # The default only keeps other services usable without it; run-client
        # always sets a real directory.
        source: "${SYNCBOX_CLIENT_DIR:-/nonexistent/SYNCBOX_CLIENT_DIR-unset}"
        target: /work
        bind:
          create_host_path: false

  test:
    build:
      context: .
      target: test
    profiles: [test]
    init: true
    # Tests only talk to servers they start themselves on loopback.
    network_mode: none

  # Toolbox for dependency management without Node on the host, e.g.
  #   docker compose run --rm dev npm install --save-dev <pkg>
  dev:
    image: node:20-bookworm-slim
    profiles: [dev]
    working_dir: /app
    user: "${SYNCBOX_UID:-1000}:${SYNCBOX_GID:-1000}"
    environment:
      npm_config_cache: /tmp/.npm
      npm_config_update_notifier: "false"
    volumes:
      - type: bind
        source: .
        target: /app
# syntax=docker/dockerfile:1

# --- dependencies (incl. dev: TypeScript, type definitions) ---------------
FROM node:20-bookworm-slim AS deps
WORKDIR /app
COPY package.json package-lock.json ./
RUN npm ci --no-audit --no-fund

# --- compile server and client sources ------------------------------------
FROM deps AS build
COPY tsconfig.json tsconfig.build.json ./
COPY src ./src
RUN npm run build

# --- test image: compiled sources + compiled tests ------------------------
FROM build AS test
COPY bin ./bin
COPY test ./test
RUN npm run build:test
CMD ["npm", "test", "--silent"]

# --- runtime base: production dependencies and compiled sources only ------
FROM node:20-bookworm-slim AS runtime
ENV NODE_ENV=production
WORKDIR /app
COPY package.json package-lock.json ./
RUN npm ci --omit=dev --no-audit --no-fund && npm cache clean --force
COPY --from=build /app/dist/src ./dist/src

# --- server image ---------------------------------------------------------
FROM runtime AS server
USER node
EXPOSE 8080
CMD ["node", "dist/src/main.js"]

# --- client image: the `syncbox` CLI --------------------------------------
FROM runtime AS client
COPY bin/syncbox ./bin/syncbox
RUN ln -s /app/bin/syncbox /usr/local/bin/syncbox
USER node
ENTRYPOINT ["syncbox"]
{
  "name": "syncbox",
  "version": "0.1.0",
  "private": true,
  "description": "Self-hosted file storage with sync: HTTP server + CLI client",
  "type": "module",
  "engines": {
    "node": ">=20 <21"
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "build:test": "tsc -p tsconfig.json",
    "test": "node --test --test-reporter=spec dist/test/",
    "start": "node dist/src/main.js"
  },
  "devDependencies": {
    "@types/node": "~20.19.43",
    "typescript": "~5.9.3"
  }
}

