      const { code, stderr } = await runSyncbox(["push", dir, "--server", "http://127.0.0.1:6000"]);
      assert.equal(code, 0, stderr);
      assert.equal((await remoteBlobs(badPort)).get("p.txt"), sha256("p"));
    } finally {
      await badPort.close();
    }
  });

