    const dir = join(root, "unreachable");
    await writeTree(dir, { "u.txt": "u" });
    const { code, stdout, stderr } = await runSyncbox(["push", dir, "--server", `http://127.0.0.1:${await freePort()}`]);
    assert.equal(code, 1);
    assert.equal(stdout, "");
